                l += 1
                # Ensure l doesn't exceed r
                if l > r:
                    l = r
            else:
                # Create sorted list of candidates
                candidates = []
                for char, positions in q.items():
                    if len(positions) == k:
                        candidates.append((positions[0], char))

                # Sort candidates by position in reverse order
                candidates.sort(key=lambda x: x[0], reverse=True)

                # Count valid complete substrings
                for p, char in candidates:
                    # Check if substring from p to r forms a complete substring
                    # We need to verify that every character in [p, r] appears exactly k times
                    # and adjacent characters differ by at most 2
                    substring = word[p:r+1]
                    # Check frequency condition
                    freq = {}
                    for ch in substring:
                        freq[ch] = freq.get(ch, 0) + 1
                    # Check if all characters appear exactly k times
                    valid_freq = True
                    for ch in freq:
                        if freq[ch] != k:
                            valid_freq = False
                            break

                    # Check adjacency condition
                    valid_adj = True
                    for i in range(1, len(substring)):
                        if abs(ord(substring[i]) - ord(substring[i-1])) > 2:
                            valid_adj = False
                            break

                    if valid_freq and valid_adj:
                        ans += 1

        return ans

