    def numberOfGoodPartitions(self, nums: List[int]) -> int:
        MOD = 1000000007
        ii = -1
        p = -1
        last = {}

        # Build last occurrence map
        for i, x in enumerate(nums):
            last[x] = i

        # Iterate through each index
        for i, x in enumerate(nums):
            # Update ii to the maximum of current ii and last occurrence of x
